   "options": [
    {
     "id": "7b035c5221",
     "text": "The larger model, because bigger models are always the better choice in production",
     "why": "Bigger isn't always better. Extra capability that isn't needed just adds cost and latency."
    },
    {
     "id": "ea1515a0f0",
     "text": "The model with the most parameters, because parameter count matters more than cost",
     "why": "Parameter count is only a rough proxy for capability, and cost matters at this scale."
    },
    {
     "id": "c6244a375d",
     "text": "The model with the longest maximum output, because classifications need long answers",
     "why": "A category label is a few tokens; a long maximum output is irrelevant."
    },
    {
     "id": "b64f58c059",
     "text": "The smaller model, because it meets the bar at lower cost and latency"
    }
   ],
   "answer": [
    "b64f58c059"
   ],
   "explanation": "When two models meet the quality bar, cost and latency decide. At tens of millions of requests a month, a smaller, simpler model can save a lot of money and respond faster, without any loss in the required quality.",
   "resource": "https://docs.aws.amazon.com/bedrock/latest/userguide/model-cards.html"
